=== CheckDigit ===
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code checkDigit}: the single Luhn check digit (0-9) computed over the digits
 * contained in the owner's {@code customerCode}, ignoring any non-digit separators. Purely derived
 * from the stored code, so no state is kept.
 */
public final class CheckDigit {

    private CheckDigit() {
    }

    public static int of(Owner owner) {
        String code = owner.getCustomerCode();
        int sum = 0;
        boolean dbl = true;
        for (int i = code.length() - 1; i >= 0; i--) {
            char c = code.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

